#!/usr/bin/env sh
# fetch Wemapp (IT) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="http://www.openbasilicata.org/dataset/ad8b732b-ca9a-4e5b-9ab3-494c268947aa/resource/11216eba-7762-4c8a-b1f8-8f74ddea3b0a/download/Potenzagtfs.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
